INSERT INTO projects (id,utility_id,name,type,voltage_kv,capacity_mw,geom,location_precision,construction,schedule_precision,in_service,status,description,county,state,resources) VALUES ('gp-mcintosh-purrysburg-230kv','georgia-power-co','McIntosh-Purrysburg 230 kV reactors and rebuilds','transmission_line_upgrade',230,NULL,ST_GeomFromGeoJSON('{"type":"Point","coordinates":[-81.175112,32.352116]}')::geography,'approximate',daterange('2025-09-01', '2026-07-01'),'estimated','2026-06-01','planned','Install reactors on the McIntosh-Purrysburg 230 kV tie lines and rebuild the short Georgia Power sections at McIntosh. The sponsor challenge reference supplies the June 2026 target and the McIntosh coordinate, but does not resolve Purrysburg; this record therefore locates only the known McIntosh endpoint as an approximate Point and does not claim a complete route. The construction window is inferred and is not a published schedule.','Effingham','GA',ARRAY['conductor','cranes','line_crews','stringing_equipment','structures']::text[]);
INSERT INTO sources (project_id,url,title,publisher,retrieved,quote,page) VALUES ('gp-mcintosh-purrysburg-230kv','https://www.southeasternrtp.com/docs/general/2024/2024_Regional_Transmission_Plan_and_Input_Assumptions.pdf','2024 Regional Transmission Plan and Input Assumptions','Southeastern Regional Transmission Planning (SERTP)','2026-09-27','In-Service Year: 2026. Project Name: MCINTOSH - PURRYSBURG 230KV REACTORS. Description: Install reactors on the McIntosh - Purrysburg (Black and White) 230kV tie lines at McIntosh. Rebuild 0.1 miles (GPC portion) for both lines to (2) 200C 1351 ACSS conductor.',77);
